#!/bin/bash\nset -euo pipefail\n\npython3 -m venv venv --prompt orch\nsource venv/bin/activate\npip install --upgrade pip\npip install -r requirements.txt pyinstaller\n\npyinstaller orch_cli.py \\\n  --onefile \\\n  --name orch \\\n  --strip \\\n  --clean \\\n  --noconsole  # optional, for GUI but CLI ok\n\ncp dist/orch .\ndeactivate\nrm -rf venv build dist *.spec\nchmod +x orch\necho "✅ Built orch (Linux x64) binary."